insert into public.hobbies(slug,name,content) values('tennis','Tennis','{"id":"tennis","name":"Tennis","icon":"🎾","color":"#D98C8C","description":"Find your rhythm. One rally at a time.","prefix":"ten","safetyNote":"Check the court, warm up gently, keep clear of others and stop if you feel pain.","resource":{"title":"USTA learning resources","url":"https://www.usta.com/en/home/improve.html"},"practicePrerequisites":["ten-safety"],"startSummary":"Borrow a racquet · TECHNIQUE-HEAVY"}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.hobbies(slug,name,content) values('cycling','Cycling / Fixed Gear','{"id":"cycling","name":"Cycling / Fixed Gear","icon":"🚲","color":"#D6B65C","description":"A little farther. A little more freedom.","prefix":"cyc","safetyNote":"Check air, brakes and chain before every ride. Use a fitted helmet and follow local traffic rules. Fixed-gear road use needs a functional front brake; do not learn brakeless street riding.","resource":{"title":"League of American Bicyclists","url":"https://bikeleague.org/ridesmart/"},"practicePrerequisites":["cyc-safety","cyc-check"],"startSummary":"Bike + helmet · GEAR NEEDED"}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.hobbies(slug,name,content) values('swimming','Swimming','{"id":"swimming","name":"Swimming","icon":"🏊","color":"#72B7A4","description":"Build confidence, one length at a time.","prefix":"swi","safetyNote":"Practice with qualified supervision in a swim-safe environment. Never swim alone, hyperventilate or do breath-holding contests. Restrictive knee bands are not a default freestyle correction.","resource":{"title":"American Red Cross water safety","url":"https://www.redcross.org/get-help/how-to-prepare-for-emergencies/types-of-emergencies/water-safety.html"},"practicePrerequisites":["swi-safety"],"startSummary":"Pool + supervision · SAFETY FIRST"}'::jsonb) on conflict(slug) do update set content=excluded.content;
