insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='tennis'),'ten-start','Welcome to Tennis','{"id":"ten-start","hobbyId":"tennis","slug":"ten-start","title":"Welcome to Tennis","tier":"start","nodeType":"orientation","xpReward":20,"requires":[],"orGroups":[],"completion":{"prompt":"Read overview and choose a first goal","evidenceMode":"note"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":0,"tags":["Athletics","Knowledge"],"category":"Orientation","position":{"x":450,"y":0},"shortDescription":"Tennis rewards control and cooperation before power.","whyItMatters":"Tennis rewards control and cooperation before power.","instructions":["Choose a wall or beginner-friendly court","Set a small goal, such as making clean contact","Arrange a relaxed first session."],"learningObjectives":["Choose a wall or beginner-friendly court","Read overview and choose a first goal","Recognize and avoid the common mistake below."],"commonMistakes":["Trying to hit hard before finding a repeatable contact point."],"safetyNotes":["Check the court, warm up gently, keep clear of others and stop if you feel pain."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USTA learning resources","url":"https://www.usta.com/en/home/improve.html","placeholder":true}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
